import json, os, time
from datetime import datetime, timezone

skill_json_path = r'C:\Users\dongbaolei\.copaw\workspaces\RA-agent\skill.json'

# Two source directories
src1 = r'C:\Users\dongbaolei\.copaw\workspaces\RA-agent\skills'      # copaw builtin
src2 = r'C:\Users\dongbaolei\.agents\skills'                          # user skills

# === Skills to enable ===
enable_set = {
    'brave-search', 'web-to-markdown', 'baoyu-url-to-markdown', 'web-to-doc',
    'source-driven-development', 'context-engineering',
    'pdf', 'docx', 'doc-coauthoring', 'documentation-and-adrs',
    'xlsx', 'excel-analysis', 'excel-financial-analysis', 'stock-analysis',
    'rag-implementation', 'llm-evaluation',
    'idea-refine', 'planning-and-task-breakdown', 'spec-driven-development',
    'requirement-analysis', 'business-license-review',
    'browser_cdp', 'file_reader',
}

now_ts = int(time.time() * 1000)
now_iso = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ')[:-4] + 'Z'

def parse_front_matter(content):
    name = ''
    description = ''
    in_fm = False
    for line in content.split('\n'):
        s = line.strip()
        if s == '---':
            if not in_fm:
                in_fm = True; continue
            else:
                break
        if in_fm:
            if s.startswith('name:'):
                name = s.split(':', 1)[1].strip()
            elif s.startswith('description:'):
                description = s.split(':', 1)[1].strip().strip('"').strip("'")
    return name, description

def scan_dir(base_dir):
    result = {}
    if not os.path.isdir(base_dir):
        return result
    for entry in os.listdir(base_dir):
        ep = os.path.join(base_dir, entry)
        if not os.path.isdir(ep):
            continue
        sm = os.path.join(ep, 'SKILL.md')
        if not os.path.exists(sm):
            sm = os.path.join(ep, 'skill.md')
        if not os.path.exists(sm):
            continue
        with open(sm, 'r', encoding='utf-8') as f:
            content = f.read()
        name, desc = parse_front_matter(content)
        if not name:
            name = entry
        if not desc:
            desc = f'Skill: {name}'
        result[entry] = (name, desc)
    return result

# Scan both sources (src1=copaw builtin takes priority for duplicates)
skills = {}

# Scan workspace first (copaw builtins)
for k, (name, desc) in scan_dir(src1).items():
    skills[k] = (name, desc, 'builtin')

# Then user skills (overwrite if duplicate - user version wins)
for k, (name, desc) in scan_dir(src2).items():
    skills[k] = (name, desc, 'custom')

# Build manifest
manifest_skills = {}
for key, (name, desc, source) in sorted(skills.items()):
    is_enabled = key in enable_set
    manifest_skills[key] = {
        "enabled": is_enabled,
        "channels": ["all"],
        "source": source,
        "metadata": {
            "name": name,
            "description": desc,
            "version_text": "1.0",
            "commit_text": "",
            "source": source,
            "protected": False,
            "requirements": {"require_bins": [], "require_envs": []},
            "updated_at": now_iso
        },
        "requirements": {"require_bins": [], "require_envs": []},
        "updated_at": now_iso,
        "config": {}
    }

manifest = {
    "schema_version": "workspace-skill-manifest.v1",
    "version": now_ts,
    "skills": manifest_skills
}

with open(skill_json_path, 'w', encoding='utf-8') as f:
    json.dump(manifest, f, ensure_ascii=False, indent=2)

total = len(manifest_skills)
on = sum(1 for s in manifest_skills.values() if s['enabled'])
builtin_count = sum(1 for s in manifest_skills.values() if s['source'] == 'builtin')
custom_count = sum(1 for s in manifest_skills.values() if s['source'] == 'custom')

print(f'Total: {total} skills ({builtin_count} builtin + {custom_count} custom)')
print(f'Enabled: {on}')

off_but_wanted = [k for k in enable_set if k in manifest_skills and not manifest_skills[k]['enabled']]
missing = [k for k in enable_set if k not in manifest_skills]
if off_but_wanted:
    print(f'NOT ENABLED (error): {off_but_wanted}')
if missing:
    print(f'MISSING FROM DISK: {missing}')
if not off_but_wanted and not missing:
    print('All target skills enabled OK!')

print(f'\nEnabled list:')
for k in sorted(manifest_skills):
    if manifest_skills[k]['enabled']:
        print(f'  [ON] {k} ({manifest_skills[k]["source"]})')

